CREATE OR REPLACE FUNCTION public.handheld_work_items_scoped(p_user_id uuid,p_location_ids uuid[],p_include_unlocated boolean DEFAULT false,p_limit integer DEFAULT 50,p_cursor_ts timestamptz DEFAULT NULL,p_cursor_id uuid DEFAULT NULL,p_support_location_ids uuid[] DEFAULT NULL,p_support_include_unlocated boolean DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public AS $$
 WITH locs AS(SELECT coalesce(p_location_ids,'{}'::uuid[]) ids),cards AS(
 SELECT m.conversation_id,m.measurement_task_id,t.created_at,t.listing_id,t.sku_id FROM support_messages m JOIN product_measurement_tasks t ON t.id=m.measurement_task_id JOIN support_conversations sc ON sc.id=m.conversation_id AND sc.location_id=t.location_id JOIN product_measurement_requesters q ON q.task_id=t.id AND q.customer_id=sc.customer_id AND q.conversation_id=sc.id WHERE m.card_kind='measurement_request' AND t.status IN ('pending','claimed')),
 sup AS(SELECT sc.*,(SELECT count(*) FROM cards c WHERE c.conversation_id=sc.id) pmc,(SELECT min(c.created_at) FROM cards c WHERE c.conversation_id=sc.id) card_at,(SELECT c.sku_id FROM cards c WHERE c.conversation_id=sc.id ORDER BY c.created_at LIMIT 1) card_sku,public.support_needs_reply(sc.id) needs_reply FROM support_conversations sc,locs WHERE sc.location_id=ANY(coalesce(p_support_location_ids,locs.ids)) OR(coalesce(p_support_include_unlocated,p_include_unlocated) AND sc.location_id IS NULL)),
 all_items AS(
 SELECT s.id,'support'::text type,'customers'::text cat,coalesce(least(s.waiting_since,s.card_at),s.waiting_since,s.card_at,s.created_at) sort_ts,coalesce(s.title,'客户咨询') title,concat_ws(' · ',CASE WHEN s.needs_reply THEN CASE WHEN s.primary_agent_id IS NULL THEN '待接待' ELSE '待回复' END END,CASE WHEN s.pmc>0 THEN '尺寸申请 '||s.pmc||' 件' END) description,'support_conversation'::text action,s.id target_id,s.card_sku sku_id,s.id conversation_id,CASE WHEN s.context->>'type'='product' THEN s.context->>'id' END listing_id FROM sup s WHERE s.needs_reply OR s.pmc>0
 UNION ALL SELECT t.id,'measurement','customers',t.created_at,'尺寸测量 '||coalesce(k.name,''),CASE WHEN t.status='claimed' THEN '测量中' ELSE '顾客申请测量，待处理' END,'measurement_task',t.id,t.sku_id,NULL::uuid,t.listing_id::text FROM product_measurement_tasks t LEFT JOIN inv_skus k ON k.id=t.sku_id,locs WHERE t.status IN ('pending','claimed') AND (t.location_id=ANY(locs.ids) OR(p_include_unlocated AND t.location_id IS NULL)) AND NOT EXISTS(SELECT 1 FROM cards c WHERE c.measurement_task_id=t.id)
 UNION ALL SELECT f.id,'commerce_pick','orders',f.created_at,'商城拣货 '||coalesce(o.order_no,f.code),CASE WHEN o.fulfillment_method='pickup' THEN '自提待备货/领取' WHEN f.status IN ('picked','packing','packed','handover_ready') THEN '待发货/交接' WHEN f.status='picking' THEN '拣货中' ELSE '待备货/异常处理' END,'fulfillment_detail',f.id,NULL::uuid,NULL::uuid,NULL::text FROM fulfillments f JOIN commerce_orders o ON o.id=f.order_id,locs WHERE f.status IN ('unallocated','allocated','picking','picked','packing','packed','handover_ready','exception') AND f.location_id=ANY(locs.ids) AND o.order_status NOT IN ('cancelled','closed') AND o.payment_status IN ('paid','refund_pending','partially_refunded')
 UNION ALL SELECT x.id,CASE WHEN x.status IN ('shipped','in_transit') THEN 'transfer_in' ELSE 'transfer_out' END,'internal',coalesce(x.shipped_at,x.created_at),'调拨入库 '||x.code,'共 '||x.qty||' 件，待验收入库','transfer_detail',x.id,NULL::uuid,NULL::uuid,NULL::text FROM stock_transfers x,locs WHERE(x.status IN ('shipped','in_transit') AND x.to_location_id=ANY(locs.ids)) OR(x.status IN ('draft','approved','failed') AND x.from_location_id=ANY(locs.ids))
 UNION ALL SELECT st.id,'stocktake','internal',coalesce(st.opened_at,st.created_at),'盘点 '||st.code,'盘点进行中，待提交','stocktake_detail',st.id,NULL::uuid,NULL::uuid,NULL::text FROM stocktakes st,locs WHERE st.status IN ('open','scanning','submitted') AND st.location_id=ANY(locs.ids)
 UNION ALL SELECT a.id,'after_sale','orders',a.created_at,'售后 '||coalesce(a.after_sale_no,''),'待处理售后','after_sale_detail',a.id,NULL::uuid,NULL::uuid,NULL::text FROM commerce_after_sales a,locs WHERE a.status IN ('requested','store_reviewing','store_received','inspecting','refund_pending') AND a.location_id=ANY(locs.ids)
 UNION ALL SELECT z.id,'stock_sync','system',z.created_at,'库存同步失败','待核查','sync_detail',z.id,NULL::uuid,NULL::uuid,NULL::text FROM youzan_stock_sync_queue z WHERE z.status='failed' AND EXISTS(SELECT 1 FROM inv_locations l,locs WHERE l.id=ANY(locs.ids) AND l.shop_id=z.shop_id)
 UNION ALL SELECT z.id,'channel_sync','system',z.created_at,'渠道同步失败','待核查','sync_detail',z.id,NULL::uuid,NULL::uuid,NULL::text FROM channel_sync_outbox z WHERE z.status IN ('failed','dead','dead_letter') AND(EXISTS(SELECT 1 FROM inv_locations l,locs WHERE l.id=ANY(locs.ids) AND l.shop_id=z.shop_id) OR(p_include_unlocated AND z.shop_id IS NULL))),
 counts AS(SELECT count(*) FILTER(WHERE cat='customers') customers,count(*) FILTER(WHERE cat='internal') internal,count(*) FILTER(WHERE cat='orders') orders,count(*) FILTER(WHERE cat='system') system FROM all_items),
 page AS(SELECT * FROM all_items WHERE p_cursor_ts IS NULL OR(sort_ts,id)>(p_cursor_ts,p_cursor_id) ORDER BY sort_ts,id LIMIT greatest(coalesce(p_limit,50),0)+1),numbered AS(SELECT p.*,row_number() OVER(ORDER BY sort_ts,id) rn FROM page p)
 SELECT jsonb_build_object('items',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'type',type,'title',title,'description',description,'sort_ts',sort_ts,'action',action,'target_id',target_id,'sku_id',sku_id,'conversation_id',conversation_id,'listing_id',listing_id) ORDER BY rn) FROM numbered WHERE rn<=greatest(coalesce(p_limit,50),0)),'[]'::jsonb),'has_more',(SELECT count(*) FROM numbered)>greatest(coalesce(p_limit,50),0),'last_ts',(SELECT sort_ts FROM numbered WHERE rn=greatest(coalesce(p_limit,50),0)),'last_id',(SELECT id FROM numbered WHERE rn=greatest(coalesce(p_limit,50),0)),'counts',(SELECT jsonb_build_object('customers',customers,'internal',internal,'orders',orders,'system',system,'total',customers+internal+orders+system) FROM counts))
$$;
CREATE OR REPLACE FUNCTION public.handheld_pending_counts_scoped(p_user_id uuid,p_location_ids uuid[],p_include_unlocated boolean DEFAULT false,p_support_location_ids uuid[] DEFAULT NULL,p_support_include_unlocated boolean DEFAULT NULL)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public AS $$ SELECT public.handheld_work_items_scoped(p_user_id,p_location_ids,p_include_unlocated,0,NULL,NULL,p_support_location_ids,p_support_include_unlocated)->'counts' $$;
REVOKE ALL ON FUNCTION public.handheld_work_items_scoped(uuid,uuid[],boolean,integer,timestamptz,uuid,uuid[],boolean), public.handheld_pending_counts_scoped(uuid,uuid[],boolean,uuid[],boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.handheld_work_items_scoped(uuid,uuid[],boolean,integer,timestamptz,uuid,uuid[],boolean), public.handheld_pending_counts_scoped(uuid,uuid[],boolean,uuid[],boolean) TO service_role;

